from itertools import product, combinations
from collections import Counter


def _route(minimum_duration, exact):
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        start = data["start"]
        initial = (source, initial_mask, 0)
        distances = {initial: start}
        queue = [(start, source, initial_mask, 0)]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        while queue:
            time, node, mask, used = heapq.heappop(queue)
            state = (node, mask, used)
            if distances.get(state) != time:
                continue
            if (node == data["target"] and mask == full and
                    (used == data["coupons"] if exact else used <= data["coupons"])):
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], used)]
                if used < data["coupons"]:
                    duration = max(minimum_duration,
                                   edge["duration"] - edge.get("discount", 0))
                    options.append((duration, used + 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for duration, next_used in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, next_used)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, edge["v"],
                                               next_mask, next_used))
        return {"arrival": None}
    return solve


def _ledger(data):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    rounding = data["rounding"]

    def rounded(numerator):
        if rounding == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        account = event.get("account", "default")
        currency = event.get("currency", "USD")
        key = account + "|" + currency
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        choices.append([None] + versions)

    best = None
    best_vector = None
    for assignment_values in product(*choices):
        assigned = dict(zip(names, assignment_values))

        valid = True
        for name, version in assigned.items():
            if version is not None and (
                    version in blocked.get(name, []) or
                    (name in pins and version != pins[name])):
                valid = False
                break
        if not valid:
            continue
        for name, bounds in roots.items():
            version = assigned.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        rows_by_name = {
            name: {row["version"]: row for row in packages[name]}
            for name in names
        }
        edges = {}
        closure = set()
        pending = list(roots)
        while pending and valid:
            name = pending.pop()
            if name in closure:
                continue
            version = assigned.get(name)
            if version is None:
                valid = False
                break
            closure.add(name)
            row = rows_by_name[name][version]
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                target_version = assigned.get(target)
                if (target_version is None or
                        not dep["min"] <= target_version <= dep["max"]):
                    valid = False
                    break
                active.append(target)
                pending.append(target)
            edges[name] = active
        if not valid or any(version is not None and name not in closure
                            for name, version in assigned.items()):
            continue

        finished = set()
        active = set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(dep) for dep in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in closure):
            continue
        vector = tuple(-1 if assigned[name] is None else assigned[name]
                       for name in names)
        if best_vector is None or vector > best_vector:
            best_vector = vector
            best = {name: assigned[name] for name in names
                    if assigned[name] is not None}

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    options = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in options}):
        return {"error": "impossible"}

    best_ids = None
    best_value = None
    for selected in combinations(options, k):
        ids = {job["id"] for job in selected}
        if not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in selected)
        if any(not low <= counts[group] <= high
               for group, (low, high) in data.get("quotas", {}).items()):
            continue

        ends = []
        compatible = True
        for job in sorted(selected, key=lambda item: (item["start"], item["end"])):
            ends = [end for end in ends if end > job["start"]]
            ends.append(job["end"])
            if len(ends) > 2:
                compatible = False
                break
        if not compatible:
            continue

        sorted_ids = tuple(sorted(ids))
        value = sum(job["value"] for job in selected)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids < best_ids)):
            best_value = value
            best_ids = sorted_ids

    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


